mapper.select:
SELECT task_pickup_dispatch.id, task_pickup_dispatch.order_id, task_pickup_dispatch.task_type, task_pickup_dispatch.status, task_pickup_dispatch.sign_status, task_pickup_dispatch.org_id, task_pickup_dispatch.courier_id, task_pickup_dispatch.assigned_status, task_pickup_dispatch.estimated_start_time, task_pickup_dispatch.actual_start_time, task_pickup_dispatch.estimated_end_time, task_pickup_dispatch.actual_end_time, task_pickup_dispatch.confirm_time, task_pickup_dispatch.cancel_time, task_pickup_dispatch.mark, task_pickup_dispatch.create_time FROM work_pickup_dispatch_task task_pickup_dispatch LEFT JOIN oms_order pdorder ON task_pickup_dispatch.order_id=pdorder.id
LEFT JOIN work_transport_order transport_order ON pdorder.id=transport_order.order_id
LEFT JOIN sys_user auth_user ON task_pickup_dispatch.courier_id = auth_user.id
AND task_pickup_dispatch.deleted = 0
AND task_pickup_dispatch.task_type = #{params.taskType}
AND task_pickup_dispatch.status = #{params.status}
AND transport_order.id LIKE CONCAT('%',#{params.transportOrderId},'%')
AND auth_user.name LIKE CONCAT('%',#{params.courierName},'%')
AND pdorder.sender_name LIKE CONCAT('%',#{params.senderName},'%')
AND pdorder.sender_province_id = #{params.senderProvinceId}
AND pdorder.sender_city_id = #{params.senderCityId}
AND pdorder.receiver_name LIKE CONCAT('%',#{params.receiverName},'%')
AND pdorder.receiver_province_id = #{params.receiverProvinceId}
AND pdorder.receiver_city_id = #{params.receiverCityId}
order by task_pickup_dispatch.create_time desc

SELECT
transport_order.id,
transport_order.order_id,
transport_order.status,
transport_order.scheduling_status,
transport_order.create_time
FROM work_transport_order transport_order


    LEFT JOIN oms_order pdorder ON transport_order.order_id = pdorder.id


    AND transport_order.deleted = 0

        AND transport_order.id LIKE CONCAT('%',#{params.id},'%')


        AND transport_order.status = #{params.status}


        AND transport_order.status IN

            #{s}



        AND transport_order.scheduling_status = #{params.schedulingStatus}


        AND pdorder.sender_name LIKE CONCAT('%',#{params.senderName},'%')


        AND pdorder.sender_phone LIKE CONCAT('%',#{params.senderPhone},'%')


        AND pdorder.sender_province_id = #{params.senderProvinceId}


        AND pdorder.sender_city_id = #{params.senderCityId}


        AND pdorder.sender_county_id = #{params.senderCountyId}


        AND pdorder.receiver_name LIKE CONCAT('%',#{params.receiverName},'%')


        AND pdorder.receiver_phone LIKE CONCAT('%',#{params.receiverPhone},'%')


        AND pdorder.receiver_province_id = #{params.receiverProvinceId}


        AND pdorder.receiver_city_id = #{params.receiverCityId}


        AND pdorder.receiver_county_id = #{params.receiverCountyId}


order by transport_order.create_time desc
